#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long long n = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (n < 2) {
        puts("NONE");
        return 0;
    }
    int first = 1;
    for (long long d = 2; d * d <= n; ++d) {
        if (n % d == 0) {
            int exp = 0;
            while (n % d == 0) {
                n /= d;
                ++exp;
            }
            if (!first) putchar(' ');
            printf("%lld^%d", d, exp);
            first = 0;
        }
    }
    if (n > 1) {
        if (!first) putchar(' ');
        printf("%lld^1", n);
    }
    putchar('\n');
    return 0;
}
